algorithms.pseudocode:
Algorithm StrongBlockingThreshold(n, D):
  // n = q^2+q+1 points; D = perfect difference set defining the lines
  1. lines <- { {(i+d) mod n : d in D} : i = 0..n-1 }
  2. best <- n+1 ; extremal <- []
  3. for each subset S of {0..n-1} (in increasing size r):
  4.     if for every line L in lines, |L ∩ S| >= 2 then   // double blocking
  5.         if r < best: best <- r ; extremal <- [S]
  6.         else if r == best: append S to extremal
  7. return (best, extremal)
  // For Fano: n=7, D={0,1,3} -> best=6, |extremal|=7, and 6=(k-1)(q+1).
